package menus

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	gamestate "gunship2000-assets/game/state"
)

// A labelled staged sequence, not a continuous flight or manufactured result:
// first actual guided firing completes both generated objectives; next mission
// is generated by the real final-ack successor, then ends via real base contact.
func TestConsecutiveCampaignCombatSuccessThenFailure(t *testing.T) {
	c := developmentScenarioController(t, "campaign-ongoing-success")
	initial := c.Store.State().SelectedPilot()
	initialCounter, initialCareer := initial.Statistics.MissionCampaignCounter, initial.Statistics.CareerScore
	fireScenarioObjectives(t, c)
	scenarioSafeReturn(t, c)
	first := c.Debrief.Pending.Proposal
	if !first.Success || first.Score.NormalizedFlags&0x83 != 0x83 || first.Result.Campaign == nil || first.Result.Campaign.Quality != 200 || first.Result.Campaign.Concluded || first.Result.Campaign.Campaign.ResultCounters != [2]int{1, 0} {
		t.Fatal("real two-objective firing/return did not yield ongoing success", first.Score, first.Result.Campaign)
	}
	// Source objective bonuses are100+50. Campaign quality200 is a separate
	// domain; unsettled dying objects need not contribute final raw points yet.
	if first.Score.Score <= 0 || int16(first.Score.AfterObjectiveBonus-first.Score.AfterObjectCredit) != 150 {
		t.Fatal("success lacked original two-objective bonus", first.Score)
	}
	firstID, firstScore := first.Facts.SortieID, first.Score.Score
	firstPages := loopAcknowledge(t, c)
	if c.Screen != ScreenInterstitial || c.Mission == nil || c.Debrief != nil {
		t.Fatal("first success did not durably prepare actual next briefing", c.Screen)
	}
	committed1 := c.Store.State()
	if committed1.SelectedPilot().Statistics.MissionCampaignCounter != initialCounter+1 || committed1.SelectedPilot().Statistics.CareerScore != initialCareer+firstScore {
		t.Fatal("first final acknowledgement did not publish actual result exactly once")
	}
	// The next draft already exists. Redraw and obsolete acknowledgement must not
	// regenerate it or reapply the previous award while the next pages load.
	next := c.Mission
	if err := c.Store.CommitSortie(firstID); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		c.Frame(false)
		if err := c.commitDebriefResult(); err != nil {
			t.Fatal(err)
		}
	}
	if c.Mission != next || !reflect.DeepEqual(committed1, c.Store.State()) {
		t.Fatal("duplicate successor changed draft or durable result")
	}
	for i := 0; i < 100 && c.Screen == ScreenInterstitial; i++ {
		if err := c.Tick(); err != nil {
			t.Fatal(err)
		}
	}
	if c.Screen != ScreenBriefing {
		t.Fatal("real next preparation did not reach briefing", c.Screen)
	}
	startRendering(t, c)
	if c.Mission.ResultLaunch == nil || c.Mission.ResultUnavailable != "" {
		t.Fatal("genuine second Campaign launch unavailable", c.Mission.ResultUnavailable)
	}
	if c.Mission.ResultLaunch.Start.ID == firstID {
		t.Fatal("sortie identity reused")
	}
	// Supplied second base approach only; its completion/result/credit remain
	// untouched. The original scenario observer is inert after combat-return.
	if err := c.developmentScenarioPose(c.Rendering.ResultTargets.Records[0], true, 2, 1, 0); err != nil {
		t.Fatal(err)
	}
	second := campaignNaturalBaseEnd(t, c)
	if second.Success || second.Score.NormalizedFlags&3 != 0 || second.Result.Campaign == nil || second.Result.Campaign.Campaign.ResultCounters != [2]int{1, 1} || second.Result.Campaign.Concluded {
		t.Fatal("actual second no-objective return did not follow failure path", second.Score, second.Result.Campaign)
	}
	// This short no-shoot return has no time reduction or objective/aircraft
	// contribution. The source selector-match50 is legitimate even on failure.
	wantSecond := int32(0)
	if second.Facts.SelectorMultisetMatch {
		wantSecond = 50
	}
	wantSecond = wantSecond * int32(second.Facts.Coefficient) / 10
	if second.Facts.RawScore != 0 || second.Facts.ElapsedDA >= 10800 || second.Score.Score != wantSecond {
		t.Fatal("second no-shoot source score/recommendation inputs disagree", second.Score)
	}
	secondID, secondScore := second.Facts.SortieID, second.Score.Score
	secondPages := loopAcknowledge(t, c)
	committed2 := c.Store.State()
	if c.Screen != ScreenInterstitial || c.Mission == nil || committed2.SelectedPilot().Statistics.MissionCampaignCounter != initialCounter+2 || committed2.SelectedPilot().Statistics.CareerScore != initialCareer+firstScore+secondScore {
		t.Fatal("second durable result/continuation mismatch", c.Screen)
	}
	// Verify actual stored SourceIndex recipients, not generated replacement
	// names or a display-only squadron. Independent source arithmetic is covered
	// by its table/threshold tests; this assertion exercises transaction copyback.
	var record struct {
		Proposal         *gamestate.SortieProposal    `json:"proposal"`
		CommissionChoice *bool                        `json:"commission_choice"`
		CrewChoices      *gamestate.SortieCrewChoices `json:"crew_choices"`
	}
	raw, err := os.ReadFile(filepath.Join(c.Store.Directory, "sorties", secondID+".json"))
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(raw, &record); err != nil {
		t.Fatal(err)
	}
	want, err := gamestate.ResolveSortieProposalWithChoices(record.Proposal, record.CommissionChoice != nil && *record.CommissionChoice, record.CrewChoices)
	if err != nil || !reflect.DeepEqual(want.SquadronPilots, committed2.SelectedPilot().SquadronPilots) || len(want.SquadronPilots) != 4 {
		t.Fatal("persisted actual crew copyback disagrees with immutable chosen proposal", err)
	}
	for _, id := range []string{firstID, secondID} {
		if err := c.Store.CommitSortie(id); err != nil {
			t.Fatal(err)
		}
	}
	if !reflect.DeepEqual(committed2, c.Store.State()) {
		t.Fatal("duplicate acknowledgement changed second career")
	}
	for i := 0; i < 100 && c.Screen == ScreenInterstitial; i++ {
		if err := c.Tick(); err != nil {
			t.Fatal(err)
		}
	}
	if c.Screen != ScreenBriefing {
		t.Fatal("failure continuation missing briefing", c.Screen)
	}
	if err := c.Handle(Actions{Quit: true}); err != nil {
		t.Fatal(err)
	}
	if err := c.Handle(Actions{ConfirmQuit: true}); err != nil {
		t.Fatal(err)
	}
	reopened, err := gamestate.OpenSaveStore(c.Store.Directory, "")
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(committed2, reopened.State()) {
		t.Fatal("quitting new uncommitted briefing undid completed result")
	}
	startup, err := NewFrontEnd(c.Office.Assets, reopened)
	if err != nil || startup.Screen != ScreenOffice || startup.Mission != nil {
		t.Fatal("normal restart forced an unfinished Campaign session", err)
	}
	recovery, err := reopened.RecoveryCandidate()
	if err != nil || recovery == nil {
		t.Fatal("second completed sortie lacks independent Phoenix", err)
	}
	if recovery.State.SelectedPilot().Statistics.MissionCampaignCounter != initialCounter+1 {
		t.Fatal("Phoenix was replaced by launch staging instead of previous completed result")
	}
	if err := reopened.Restore(recovery.ID); err != nil {
		t.Fatal(err)
	}
	recovered := reopened.State()
	for _, id := range []string{firstID, secondID} {
		if err := reopened.CommitSortie(id); err != nil {
			t.Fatal(err)
		}
	}
	if !reflect.DeepEqual(recovered, reopened.State()) {
		t.Fatal("Phoenix allowed a consumed result to re-award")
	}
	if again, err := reopened.RecoveryCandidate(); err != nil || again != nil {
		t.Fatal("Phoenix not consume-once", err)
	}
	last, err := gamestate.OpenSaveStore(c.Store.Directory, "")
	if err != nil || !reflect.DeepEqual(recovered, last.State()) {
		t.Fatal("recovered career changed on restart", err)
	}
	if out := os.Getenv("GS2000_N6_CAMPAIGN_EVIDENCE"); out != "" {
		if err := os.MkdirAll(out, 0700); err != nil {
			t.Fatal(err)
		}
		b, _ := json.MarshalIndent(map[string]any{"qualification": "headless native controller; labelled supplied history/approach; first actual weapons/objectives; genuine second preparation and no-objective return; not continuous flight/original observation/human acceptance", "first": first, "second": second, "first_pages": firstPages, "second_pages": secondPages, "committed_after_first": committed1, "committed_after_second": committed2, "after_explicit_phoenix": recovered}, "", "  ")
		if err := os.WriteFile(filepath.Join(out, "success-then-failure.json"), b, 0600); err != nil {
			t.Fatal(err)
		}
	}
}
